create table if not exists public.power_rankings (
  id bigint generated by default as identity primary key,
  season_id bigint not null references public.seasons (id) on delete cascade,
  week integer not null,
  team_id bigint not null references public.fantasy_teams (id) on delete cascade,
  rank integer not null,
  previous_rank integer,
  power_score numeric not null,
  all_play_score numeric not null,
  points_score numeric not null,
  recent_score numeric not null,
  record_score numeric not null,
  roster_score numeric not null,
  created_at timestamptz not null default now(),
  unique (season_id, week, team_id)
);

create index if not exists power_rankings_season_week_idx on public.power_rankings (season_id, week);

alter table public.power_rankings enable row level security;

drop policy if exists "Authenticated users can read power rankings" on public.power_rankings;
create policy "Authenticated users can read power rankings"
on public.power_rankings
for select
to authenticated
using (true);

-- ============================================================
-- 0007_fantasy_teams_final_rank.sql
-- ============================================================
-- ESPN's final standing for a completed season (team.rankCalculatedFinal /
-- team.rankFinal in the raw response) — the authoritative source for who
-- won the league, used by the Champions page. 0/absent for an in-progress
-- season.
alter table public.fantasy_teams add column if not exists final_rank integer;

-- ============================================================
-- 0008_chat.sql
-- ============================================================
-- Simple league-wide chat. Every authenticated league member can read and
-- post; a message's author is always the authenticated session's user_id
-- (never client-supplied) — the UI resolves the display name via profiles
-- at read time, never by trusting a client-sent name.

create table if not exists public.chat_messages (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  body text not null check (char_length(body) between 1 and 2000),
  created_at timestamptz not null default now()
);

create index if not exists chat_messages_created_at_idx on public.chat_messages (created_at desc);

alter table public.chat_messages enable row level security;

drop policy if exists "Authenticated users can read chat" on public.chat_messages;
create policy "Authenticated users can read chat"
on public.chat_messages
for select
to authenticated
using (true);

drop policy if exists "Users can post chat as themselves" on public.chat_messages;
create policy "Users can post chat as themselves"
on public.chat_messages
for insert
to authenticated
with check (user_id = auth.uid());

drop policy if exists "Users can delete their own messages" on public.chat_messages;
create policy "Users can delete their own messages"
on public.chat_messages
for delete
to authenticated
using (user_id = auth.uid());

do $$
begin
  if not exists (
    select 1 from pg_publication_tables
    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'chat_messages'
  ) then
    alter publication supabase_realtime add table public.chat_messages;
  end if;
end $$;

-- ============================================================
-- 0009_weekly_recaps.sql
-- ============================================================
-- Completed weekly recaps. Stored as a JSON payload (see
-- src/lib/analytics/recap.ts for the shape) rather than a column per
-- field — the recap's content is naturally a small nested document, and
-- keeping it flexible here means a later LLM-generated narrative field can
-- be added without a migration. season/week/created_at stay as real
-- columns since those are what queries filter and sort on.

create table if not exists public.weekly_recaps (
  id bigint generated by default as identity primary key,
  season_id bigint not null references public.seasons (id) on delete cascade,
  week integer not null,
  payload jsonb not null,
  created_at timestamptz not null default now(),
  unique (season_id, week)
);

create index if not exists weekly_recaps_season_week_idx on public.weekly_recaps (season_id, week);

alter table public.weekly_recaps enable row level security;

drop policy if exists "Authenticated users can read weekly recaps" on public.weekly_recaps;
create policy "Authenticated users can read weekly recaps"
on public.weekly_recaps
for select
to authenticated
using (true);

